ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  success: false,
  error: {
    code: "ORDER_NOT_FOUND",
    message: "La orden solicitada no existe: " ++ (vars.orderId default ""),
    httpStatus: 404,
    correlationId: vars.correlationId default correlationId
  }
}

%dw 2.0
output application/json
---
{
  success: false,
  error: {
    code: "DUPLICATE_SKU",
    message: "No se permiten SKUs duplicados dentro de la misma orden.",
    httpStatus: 400,
    correlationId: vars.correlationId default correlationId
  }
}

db:update.db:input-parameters:
#[{
	sku: vars.currentItem.sku,
	quantity: vars.currentItem.quantity as Number
}]

db:insert.db:sql:
INSERT INTO retail_order_items (
    order_id, sku, quantity, unit_price, subtotal
) VALUES (
    :orderId, :sku, :quantity, :unitPrice, :subtotal
)

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  success: false,
  error: {
    code: "ORDER_NOT_FOUND",
    message: "No existe la orden para actualizar sincronizacion: " ++ (vars.orderId default ""),
    httpStatus: 404,
    correlationId: vars.correlationId default correlationId
  }
}
